/// <summary>
/// UPSPricingAttribute of table <c>EcoResProductServiceWarranty</c> field DurationTime.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeEcoResProductServWarrDurationTime extends UPSPricingAttributeEcoResProductServiceWarranty implements UPSIPricingAttribute
{
}

