public str getName()
{
    return fieldPName(EcoResProductServiceWarranty, DurationTime);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Time);

    EcoResProductServiceWarranty warrantyProduct;

    while select DurationTime from warrantyProduct
        group by DurationTime
    {
        if (!ret.in(warrantyProduct.DurationTime))
        {
            ret.add(warrantyProduct.DurationTime);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(EcoResProductServiceWarranty, DurationTime));
    qbr.value(queryValue(_value));
}
